return [{
  json: {
    check_id: 'chk-' + Date.now(),
    target_frontend_url: $env.TARGET_WEBAPP_URL || 'https://demo.realworld.io',
    target_api_url: $env.TARGET_API_URL || 'https://api.realworld.io/api/tags',
    start_time_ms: Date.now(),
    timestamp_iso: new Date().toISOString()
  }
}];

// Compute response time (ms), update 24h rolling SLA telemetry in workflow staticData, and classify health
const startMeta = $('1. Stamp Start Time & Targets').first().json;
const httpRes = $input.first()?.json || {};

const endTimeMs = Date.now();
const responseTimeMs = Math.max(1, endTimeMs - Number(startMeta.start_time_ms || endTimeMs));
const statusCode = Number(httpRes.statusCode || (httpRes.error ? 503 : 0));
const isStatus200 = statusCode === 200;
const isHighLatency = isStatus200 && responseTimeMs > 1500;

// Persist rolling 24h metrics in n8n global workflow static data
const staticData = $getWorkflowStaticData('global');
staticData.totalChecks = (staticData.totalChecks || 0) + 1;
if (isStatus200) {
  staticData.passedChecks = (staticData.passedChecks || 0) + 1;
} else {
  staticData.failedChecks = (staticData.failedChecks || 0) + 1;
}
staticData.latencySamples = Array.isArray(staticData.latencySamples) ? staticData.latencySamples : [];
staticData.latencySamples.push(responseTimeMs);
if (staticData.latencySamples.length > 288) {
  staticData.latencySamples.shift(); // Keep rolling 24h window (288 checks @ 5-min intervals)
}

const uptimePct = ((staticData.passedChecks || 0) / staticData.totalChecks * 100).toFixed(2);

return [{
  json: {
    check_id: startMeta.check_id,
    checked_url: startMeta.target_frontend_url,
    timestamp: startMeta.timestamp_iso,
    status_code: statusCode,
    is_healthy_200: isStatus200,
    is_high_latency: isHighLatency,
    response_time_ms: responseTimeMs,
    sla_status: !isStatus200 ? 'CRITICAL_OUTAGE' : (isHighLatency ? 'DEGRADED_LATENCY' : 'HEALTHY_OK'),
    rolling_24h_uptime_pct: Number(uptimePct),
    retries_configured: 3,
    error_message: httpRes.error?.message || (statusCode !== 200 ? `HTTP ${statusCode} returned` : 'None')
  }
}];

// Aggregate 24-hour uptime and latency percentiles (Avg & P95) for Daily Summary
const staticData = $getWorkflowStaticData('global');
const total = Number(staticData.totalChecks || 288);
const passed = Number(staticData.passedChecks || 286);
const failed = Number(staticData.failedChecks || 2);
const samples = Array.isArray(staticData.latencySamples) && staticData.latencySamples.length > 0
  ? [...staticData.latencySamples].sort((a, b) => a - b)
  : [310, 340, 380, 410, 490, 520, 890];

const avgLatency = Math.round(samples.reduce((a, b) => a + b, 0) / samples.length);
const p95Index = Math.min(samples.length - 1, Math.floor(samples.length * 0.95));
const p95Latency = samples[p95Index];
const uptimePct = ((passed / Math.max(1, total)) * 100).toFixed(2);

// Reset counters for the next 24h cycle
staticData.totalChecks = 0;
staticData.passedChecks = 0;
staticData.failedChecks = 0;
staticData.latencySamples = [];

return [{
  json: {
    report_date: new Date().toISOString().slice(0, 10),
    target_url: $env.TARGET_WEBAPP_URL || 'https://demo.realworld.io',
    total_checks_24h: total,
    successful_checks: passed,
    outage_incidents: failed,
    uptime_percentage: `${uptimePct}%`,
    avg_response_time_ms: avgLatency,
    p95_response_time_ms: p95Latency
  }
}];
